var replaceCards = createServerFn({ method: "POST" }).middleware([authMiddleware]).validator((input) => input).handler(replaceCards_createServerFn_handler, async ({ context, data }) => {
	const { getAdminFirestore } = await import("./firebase-admin.server-6Qy3xgrH.js");
	const ref = getAdminFirestore().collection("study_sets").doc(data.id);
	const doc = await ref.get();
	if (!doc.exists || doc.data()?.ownerId !== context.userId) throw new Error("Bu seti düzenleme yetkin yok.");
	const existing = doc.data();
	const previous = new Map(existing.cards.map((c) => [c.term.trim().toLowerCase(), c]));
	const nextCards = toCards(data.cards).map((c) => {
		const prior = previous.get(c.term.toLowerCase());
		if (!prior) return c;
		return {
			...c,
			starred: prior.starred,
			mastery: prior.mastery
		};
	});
	const now = Date.now();
	await ref.update({
		cards: nextCards,
		updatedAt: now
	});
	return nextCards;
});
